"""Synthetic NTFS filesystem image generator for forensic testing."""

import hashlib
import struct
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from recoverx.domain.enums import FileSystemType


@dataclass(slots=True)
class ExpectedNtfsFile:
    """Expected file metadata recorded in synthetic NTFS image manifest."""

    filename: str
    relative_path: str
    content: bytes
    sha256_hash: str
    is_deleted: bool
    is_overwritten: bool
    is_resident: bool
    corrupt_fixup: bool
    mft_record_index: int
    size_bytes: int


@dataclass(slots=True)
class SyntheticNtfsManifest:
    """Manifest describing files and filesystem geometry generated by SyntheticNtfsBuilder."""

    image_path: Path
    filesystem_type: FileSystemType
    total_size_bytes: int
    cluster_size_bytes: int
    files: list[ExpectedNtfsFile] = field(default_factory=list)

    def get_file(self, filename: str) -> ExpectedNtfsFile | None:
        """Find an expected file by filename."""
        for f in self.files:
            if f.filename == filename:
                return f
        return None


class SyntheticNtfsBuilder:
    """Constructs valid NTFS disk images with known files, MFT records, and allocation states."""

    def __init__(
        self,
        volume_label: str = "NTFS_TEST",
        bytes_per_sector: int = 512,
        sectors_per_cluster: int = 8,  # 4096 byte clusters
        total_sectors: int = 16384,  # 8 MiB image
    ) -> None:
        self.volume_label = volume_label
        self.bytes_per_sec = bytes_per_sector
        self.sec_per_clus = sectors_per_cluster
        self.total_sectors = total_sectors
        self.cluster_size = bytes_per_sector * sectors_per_cluster

        self.mft_start_lcn = 4
        self.mft_mirr_start_lcn = 2
        self.mft_clusters = 16  # 64 KiB for MFT (64 records)

        self._files: list[dict[str, Any]] = []
        self._next_record_index = 16
        self._next_cluster = 32  # Cluster heap starts after metadata

    def add_file(
        self,
        filename: str,
        content: bytes,
        is_deleted: bool = False,
        is_directory: bool = False,
        is_resident: bool | None = None,
        is_overwritten: bool = False,
        corrupt_fixup: bool = False,
        parent_record_index: int = 5,
        relative_dir: str = "",
    ) -> int:
        """Register a file to be embedded into the synthetic NTFS image."""
        is_res = (len(content) <= 400 and not is_directory) if is_resident is None else is_resident

        rec_idx = self._next_record_index
        self._next_record_index += 1

        clus_count = (
            (len(content) + self.cluster_size - 1) // self.cluster_size if not is_res else 0
        )
        first_cluster = self._next_cluster if not is_res else 0
        if not is_res:
            self._next_cluster += max(1, clus_count)

        self._files.append(
            {
                "filename": filename,
                "relative_dir": relative_dir,
                "content": content,
                "is_deleted": is_deleted,
                "is_directory": is_directory,
                "is_resident": is_res,
                "is_overwritten": is_overwritten,
                "corrupt_fixup": corrupt_fixup,
                "parent_record_index": parent_record_index,
                "record_index": rec_idx,
                "first_cluster": first_cluster,
                "cluster_count": clus_count,
            }
        )
        return rec_idx

    def build(self, output_path: Path) -> SyntheticNtfsManifest:
        """Build and write the synthetic NTFS image to disk."""
        total_bytes = self.total_sectors * self.bytes_per_sec
        img = bytearray(total_bytes)

        # 1. Create Boot Sector at sector 0
        boot_sector = self._create_boot_sector()
        img[0:512] = boot_sector

        # Backup boot sector at the last sector
        backup_offset = (self.total_sectors - 1) * self.bytes_per_sec
        img[backup_offset : backup_offset + 512] = boot_sector

        # 2. Prepare Cluster Allocation Bitmap
        total_clusters = total_bytes // self.cluster_size
        bitmap_bytes = bytearray((total_clusters + 7) // 8)

        # Mark metadata clusters as allocated (0 to 31)
        for c in range(min(32, total_clusters)):
            bitmap_bytes[c >> 3] |= 1 << (c & 7)

        # 3. Create System MFT Records (0-15)
        mft_records: dict[int, bytes] = {}

        # Record 3: $Volume (with volume label)
        mft_records[3] = self._create_volume_record(self.volume_label)

        # Record 5: Root Directory
        mft_records[5] = self._create_directory_record(rec_idx=5, parent_idx=5, name=".")

        # 4. Create User Files MFT Records and write cluster payloads
        manifest_files: list[ExpectedNtfsFile] = []

        for f in self._files:
            rec_idx = f["record_index"]
            content = f["content"]
            is_deleted = f["is_deleted"]
            is_res = f["is_resident"]
            first_clus = f["first_cluster"]
            clus_count = f["cluster_count"]
            is_over = f["is_overwritten"]

            # Write data to cluster heap if non-resident
            if not is_res and clus_count > 0:
                data_offset = first_clus * self.cluster_size
                img[data_offset : data_offset + len(content)] = content

                # If file is active or overwritten, mark in bitmap
                if not is_deleted or is_over:
                    for c in range(clus_count):
                        target_c = first_clus + c
                        if target_c < total_clusters:
                            bitmap_bytes[target_c >> 3] |= 1 << (target_c & 7)

            # Build MFT record
            if f["is_directory"]:
                rec_bytes = self._create_directory_record(
                    rec_idx=rec_idx,
                    parent_idx=f["parent_record_index"],
                    name=f["filename"],
                    is_deleted=is_deleted,
                    corrupt_fixup=f["corrupt_fixup"],
                )
            else:
                rec_bytes = self._create_file_record(
                    rec_idx=rec_idx,
                    parent_idx=f["parent_record_index"],
                    name=f["filename"],
                    content=content,
                    is_deleted=is_deleted,
                    is_resident=is_res,
                    first_cluster=first_clus,
                    cluster_count=clus_count,
                    corrupt_fixup=f["corrupt_fixup"],
                )
            mft_records[rec_idx] = rec_bytes

            rel_p = f["filename"]
            if f["relative_dir"]:
                rel_p = f"{f['relative_dir']}/{f['filename']}"

            manifest_files.append(
                ExpectedNtfsFile(
                    filename=f["filename"],
                    relative_path=rel_p,
                    content=content,
                    sha256_hash=hashlib.sha256(content).hexdigest(),
                    is_deleted=is_deleted,
                    is_overwritten=is_over,
                    is_resident=is_res,
                    corrupt_fixup=f["corrupt_fixup"],
                    mft_record_index=rec_idx,
                    size_bytes=len(content),
                )
            )

        # Record 6: $Bitmap
        mft_records[6] = self._create_bitmap_record(bytes(bitmap_bytes))

        # Record 0: $MFT
        # Max record index
        max_rec = max([0, *list(mft_records.keys())])
        mft_total_bytes = (max_rec + 1) * 1024
        mft_records[0] = self._create_mft_meta_record(
            total_mft_bytes=mft_total_bytes,
            mft_start_lcn=self.mft_start_lcn,
            mft_cluster_count=self.mft_clusters,
        )

        # Write all MFT records to the MFT table on disk
        mft_disk_offset = self.mft_start_lcn * self.cluster_size
        for rec_idx, rec_data in mft_records.items():
            off = mft_disk_offset + (rec_idx * 1024)
            img[off : off + 1024] = rec_data

        # Also write $MFTMirr (copies of first 4 records)
        mirr_disk_offset = self.mft_mirr_start_lcn * self.cluster_size
        for rec_idx in range(4):
            if rec_idx in mft_records:
                off = mirr_disk_offset + (rec_idx * 1024)
                img[off : off + 1024] = mft_records[rec_idx]

        output_path.parent.mkdir(parents=True, exist_ok=True)
        output_path.write_bytes(bytes(img))

        return SyntheticNtfsManifest(
            image_path=output_path,
            filesystem_type=FileSystemType.NTFS,
            total_size_bytes=total_bytes,
            cluster_size_bytes=self.cluster_size,
            files=manifest_files,
        )

    def _create_boot_sector(self) -> bytes:
        """Create a 512-byte NTFS boot sector."""
        buf = bytearray(512)
        buf[0:3] = b"\xeb\x52\x90"
        buf[3:11] = b"NTFS    "
        struct.pack_into("<H", buf, 11, self.bytes_per_sec)
        buf[13] = self.sec_per_clus
        struct.pack_into("<Q", buf, 40, self.total_sectors)
        struct.pack_into("<Q", buf, 48, self.mft_start_lcn)
        struct.pack_into("<Q", buf, 56, self.mft_mirr_start_lcn)
        struct.pack_into("<b", buf, 64, -10)  # 2**10 = 1024 B
        struct.pack_into("<b", buf, 68, -12)  # 2**12 = 4096 B
        struct.pack_into("<Q", buf, 72, 0x1122334455667788)
        buf[510:512] = b"\x55\xaa"
        return bytes(buf)

    def _build_mft_record_shell(
        self,
        rec_idx: int,
        flags: int,
        corrupt_fixup: bool = False,
    ) -> bytearray:
        """Construct raw 1024-byte record buffer with header and fixup array."""
        rec = bytearray(1024)
        rec[0:4] = b"FILE"
        update_seq_offset = 42
        update_seq_count = 3  # 1 USN + 2 replacements for 2 sectors
        struct.pack_into("<HH", rec, 4, update_seq_offset, update_seq_count)
        struct.pack_into("<H", rec, 16, 1)  # Sequence number
        struct.pack_into("<H", rec, 18, 1)  # Link count
        struct.pack_into("<H", rec, 20, 56)  # First attribute offset
        struct.pack_into("<H", rec, 22, flags)
        struct.pack_into("<I", rec, 24, 1024)  # Real size
        struct.pack_into("<I", rec, 28, 1024)  # Allocated size
        struct.pack_into("<Q", rec, 32, 0)  # Base record ref
        struct.pack_into("<H", rec, 40, 1)  # Next attr id
        struct.pack_into("<I", rec, 44, rec_idx)  # Record number

        # Fixup USN
        usn = 0x5678
        struct.pack_into("<H", rec, update_seq_offset, usn)

        # Placeholders at sector ends: 510..512 and 1022..1024
        # Original bytes stored in update sequence array:
        struct.pack_into("<H", rec, update_seq_offset + 2, 0x0000)
        struct.pack_into("<H", rec, update_seq_offset + 4, 0x0000)

        # Sector ends get USN
        if corrupt_fixup:
            struct.pack_into("<H", rec, 510, 0x9999)  # Mismatched!
        else:
            struct.pack_into("<H", rec, 510, usn)
        struct.pack_into("<H", rec, 1022, usn)

        return rec

    def _create_volume_record(self, label: str) -> bytes:
        """Create MFT Record 3 ($Volume)."""
        rec = self._build_mft_record_shell(rec_idx=3, flags=0x0001)
        curr = 56

        # Standard Information
        si = self._make_resident_attr(0x10, b"\x00" * 48)
        rec[curr : curr + len(si)] = si
        curr += len(si)

        # Volume Name
        raw_label = label.encode("utf-16le")
        vn = self._make_resident_attr(0x60, raw_label)
        rec[curr : curr + len(vn)] = vn
        curr += len(vn)

        # End marker
        struct.pack_into("<I", rec, curr, 0xFFFFFFFF)
        return bytes(rec)

    def _create_directory_record(
        self,
        rec_idx: int,
        parent_idx: int,
        name: str,
        is_deleted: bool = False,
        corrupt_fixup: bool = False,
    ) -> bytes:
        """Create MFT directory record."""
        flags = 0x0002 if is_deleted else 0x0003  # 0x02 = dir, 0x01 = in-use
        rec = self._build_mft_record_shell(
            rec_idx=rec_idx, flags=flags, corrupt_fixup=corrupt_fixup
        )
        curr = 56

        # Standard Information
        si = self._make_resident_attr(0x10, b"\x00" * 48)
        rec[curr : curr + len(si)] = si
        curr += len(si)

        # File Name attribute
        fn_data = self._make_file_name_data(parent_idx=parent_idx, name=name, is_dir=True)
        fn_attr = self._make_resident_attr(0x30, fn_data)
        rec[curr : curr + len(fn_attr)] = fn_attr
        curr += len(fn_attr)

        # End marker
        struct.pack_into("<I", rec, curr, 0xFFFFFFFF)
        return bytes(rec)

    def _create_file_record(
        self,
        rec_idx: int,
        parent_idx: int,
        name: str,
        content: bytes,
        is_deleted: bool = False,
        is_resident: bool = True,
        first_cluster: int = 0,
        cluster_count: int = 0,
        corrupt_fixup: bool = False,
    ) -> bytes:
        """Create MFT regular file record."""
        flags = 0x0000 if is_deleted else 0x0001
        rec = self._build_mft_record_shell(
            rec_idx=rec_idx, flags=flags, corrupt_fixup=corrupt_fixup
        )
        curr = 56

        # Standard Information
        si = self._make_resident_attr(0x10, b"\x00" * 48)
        rec[curr : curr + len(si)] = si
        curr += len(si)

        # File Name
        fn_data = self._make_file_name_data(
            parent_idx=parent_idx,
            name=name,
            file_size=len(content),
            is_dir=False,
        )
        fn_attr = self._make_resident_attr(0x30, fn_data)
        rec[curr : curr + len(fn_attr)] = fn_attr
        curr += len(fn_attr)

        # $DATA attribute
        if is_resident:
            data_attr = self._make_resident_attr(0x80, content)
        else:
            data_attr = self._make_non_resident_attr(
                real_size=len(content),
                first_cluster=first_cluster,
                cluster_count=cluster_count,
            )
        rec[curr : curr + len(data_attr)] = data_attr
        curr += len(data_attr)

        # End marker
        struct.pack_into("<I", rec, curr, 0xFFFFFFFF)
        return bytes(rec)

    def _create_bitmap_record(self, bitmap_bytes: bytes) -> bytes:
        """Create MFT Record 6 ($Bitmap)."""
        rec = self._build_mft_record_shell(rec_idx=6, flags=0x0001)
        curr = 56

        # Standard Information
        si = self._make_resident_attr(0x10, b"\x00" * 48)
        rec[curr : curr + len(si)] = si
        curr += len(si)

        # Resident $DATA containing the bitmap
        data_attr = self._make_resident_attr(0x80, bitmap_bytes)
        rec[curr : curr + len(data_attr)] = data_attr
        curr += len(data_attr)

        # End marker
        struct.pack_into("<I", rec, curr, 0xFFFFFFFF)
        return bytes(rec)

    def _create_mft_meta_record(
        self,
        total_mft_bytes: int,
        mft_start_lcn: int,
        mft_cluster_count: int,
    ) -> bytes:
        """Create MFT Record 0 ($MFT)."""
        rec = self._build_mft_record_shell(rec_idx=0, flags=0x0001)
        curr = 56

        # Standard Information
        si = self._make_resident_attr(0x10, b"\x00" * 48)
        rec[curr : curr + len(si)] = si
        curr += len(si)

        # Non-resident $DATA mapping the MFT clusters
        data_attr = self._make_non_resident_attr(
            real_size=total_mft_bytes,
            first_cluster=mft_start_lcn,
            cluster_count=mft_cluster_count,
        )
        rec[curr : curr + len(data_attr)] = data_attr
        curr += len(data_attr)

        # End marker
        struct.pack_into("<I", rec, curr, 0xFFFFFFFF)
        return bytes(rec)

    def _make_resident_attr(self, attr_type: int, data: bytes) -> bytes:
        """Build resident attribute buffer padded to 8-byte boundary."""
        hdr_len = 24
        val_len = len(data)
        total_len = (hdr_len + val_len + 7) & ~7
        buf = bytearray(total_len)

        struct.pack_into("<I", buf, 0, attr_type)
        struct.pack_into("<I", buf, 4, total_len)
        buf[8] = 0  # Resident
        buf[9] = 0  # Name length
        struct.pack_into("<H", buf, 10, 0)
        struct.pack_into("<H", buf, 12, 0)  # Flags
        struct.pack_into("<H", buf, 14, 1)  # Attr id
        struct.pack_into("<I", buf, 16, val_len)
        struct.pack_into("<H", buf, 20, hdr_len)  # Value offset
        buf[hdr_len : hdr_len + val_len] = data
        return bytes(buf)

    def _make_non_resident_attr(
        self,
        real_size: int,
        first_cluster: int,
        cluster_count: int,
    ) -> bytes:
        """Build non-resident attribute buffer with a single data run."""
        # Encode data run:
        # Run length bytes (e.g. 2 bytes) and run offset bytes (e.g. 4 bytes)
        clus_len_bytes = (cluster_count.bit_length() + 7) // 8 or 1
        lcn_len_bytes = (first_cluster.bit_length() + 8) // 8 or 1  # +8 for signed bit

        run_hdr = (lcn_len_bytes << 4) | clus_len_bytes
        run_data = (
            bytes([run_hdr])
            + cluster_count.to_bytes(clus_len_bytes, "little", signed=False)
            + first_cluster.to_bytes(lcn_len_bytes, "little", signed=True)
            + b"\x00"  # Terminator
        )

        hdr_len = 64
        total_len = (hdr_len + len(run_data) + 7) & ~7
        buf = bytearray(total_len)

        struct.pack_into("<I", buf, 0, 0x80)  # $DATA
        struct.pack_into("<I", buf, 4, total_len)
        buf[8] = 1  # Non-resident
        buf[9] = 0
        struct.pack_into("<H", buf, 10, 0)
        struct.pack_into("<H", buf, 12, 0)
        struct.pack_into("<H", buf, 14, 1)

        struct.pack_into("<Q", buf, 16, 0)  # Start VCN
        struct.pack_into("<Q", buf, 24, max(0, cluster_count - 1))  # End VCN
        struct.pack_into("<H", buf, 32, hdr_len)  # Run list offset
        struct.pack_into("<Q", buf, 40, cluster_count * self.cluster_size)  # Alloc size
        struct.pack_into("<Q", buf, 48, real_size)  # Real size
        struct.pack_into("<Q", buf, 56, real_size)  # Initialized size

        buf[hdr_len : hdr_len + len(run_data)] = run_data
        return bytes(buf)

    def _make_file_name_data(
        self,
        parent_idx: int,
        name: str,
        file_size: int = 0,
        is_dir: bool = False,
    ) -> bytes:
        """Build payload of a $FILE_NAME attribute."""
        raw_name = name.encode("utf-16le")
        name_chars = len(name)
        total_len = 66 + len(raw_name)
        buf = bytearray(total_len)

        parent_ref = parent_idx & 0x0000FFFFFFFFFFFF
        struct.pack_into("<Q", buf, 0, parent_ref)
        struct.pack_into("<Q", buf, 40, file_size)  # Alloc size
        struct.pack_into("<Q", buf, 48, file_size)  # Real size
        flags = 0x10 if is_dir else 0x20  # Directory or Archive
        struct.pack_into("<I", buf, 56, flags)
        buf[64] = name_chars
        buf[65] = 1  # Win32 namespace
        buf[66 : 66 + len(raw_name)] = raw_name
        return bytes(buf)
